-- 운영 시연 데이터 : 2024-12 ~ 2026-11 주문 월 15건, 고객·공급처 각 20곳
-- 운영 프로필에서만 적용 (application-prod.yaml flyway.locations)
-- 회사·창고·카테고리는 유지하고 업무 데이터와 테스트 계정을 비운 뒤 다시 채운다
-- 계정은 가장 먼저 만든 활성 관리자만 남긴다 : 다른 계정은 적재 뒤 화면에서 만든다
-- 적용 후 수정·삭제 금지 : 체크섬이 달라지면 서버가 시작되지 않는다

SET @admin := (SELECT MIN(user_id) FROM users WHERE role = 'ADMIN' AND is_active = TRUE);
SET @warehouse := (SELECT MIN(warehouse_id) FROM warehouses WHERE is_default = TRUE);

-- 기존 업무 데이터 비우기 (FK 순서)
DELETE FROM sales;
DELETE FROM deliveries;
DELETE FROM order_items;
DELETE FROM orders;
DELETE FROM inventory_transactions;
DELETE FROM purchase_items;
DELETE FROM purchases;
DELETE FROM inventory_lots;
DELETE FROM inventories;
DELETE FROM items;
DELETE FROM business_partners;

-- 테스트 계정 정리 (refresh_tokens 는 ON DELETE CASCADE)
DELETE FROM users WHERE user_id <> @admin;

